CREATE OR REPLACE FUNCTION NbProjets(p_matricule IN NUMBER) RETURN NUMBER
IS
  v_nb NUMBER;
BEGIN
  SELECT COUNT(*) INTO v_nb FROM travailler WHERE matricule = p_matricule;
  RETURN v_nb;
END;

CREATE OR REPLACE PROCEDURE infoDivision(p_code_div IN NUMBER)
IS
BEGIN
  FOR p IN (SELECT code_proj, nom_proj FROM projet WHERE code_div = p_code_div) LOOP
    DBMS_OUTPUT.PUT_LINE('Projet ' || p.code_proj || ' - ' || p.nom_proj);
    FOR s IN (SELECT s.nom, s.prenom
              FROM salarie s, travailler t
              WHERE t.matricule = s.matricule AND t.code_proj = p.code_proj) LOOP
      DBMS_OUTPUT.PUT_LINE('  - ' || s.nom || ' ' || s.prenom);
    END LOOP;
  END LOOP;
END;

CREATE OR REPLACE PROCEDURE verifier_age(p_age IN NUMBER)
IS
  e_age_invalide EXCEPTION;
  PRAGMA EXCEPTION_INIT(e_age_invalide, -20001);
BEGIN
  IF p_age < 18 THEN
    RAISE e_age_invalide;
  END IF;
  DBMS_OUTPUT.PUT_LINE('Âge valide');
EXCEPTION
  WHEN e_age_invalide THEN
    DBMS_OUTPUT.PUT_LINE('Âge invalide');
END;

